func order(c Composition) []string {
	es := []string{}
	for e := range c {
		es = append(es, e)
	}
	sort.Strings(es)
	if _, ok := c["C"]; !ok {
		return es
	}
	out := []string{"C"}
	if _, ok := c["H"]; ok {
		out = append(out, "H")
	}
	for _, e := range es {
		if e != "C" && e != "H" {
			out = append(out, e)
		}
	}
	return out
func hill(c Composition, q int64) string {
	var s strings.Builder
	for _, e := range order(c) {
		s.WriteString(e)
		if c[e] != 1 {
			s.WriteString(strconv.FormatInt(c[e], 10))
		}
	}
	if q != 0 {
		s.WriteByte('^')
		if abs(q) != 1 {
			s.WriteString(strconv.FormatInt(abs(q), 10))
		}
		if q > 0 {
			s.WriteByte('+')
		} else {
			s.WriteByte('-')
		}
	}
	return s.String()
func formula(text, word string) (Formula, error) {
	p := Parser{text: text}
	c := p.sequence()
	for p.peek() == '.' {
		p.p++
		k := p.number()
		c = add(c, p.sequence(), k)
	}
	q := int64(0)
	if p.peek() == '^' {
		p.p++
		k := p.number()
		ch := p.peek()
		if ch != '+' && ch != '-' {
			p.err = true
		} else {
			p.p++
			q = k
			if ch == '-' {
				q = -q
			}
		}
	}
	if p.err || p.p != len(text) {
		return Formula{}, problem("invalid formula " + word)
	}
	for _, e := range p.seen {
		if _, ok := W[e]; !ok {
			return Formula{}, problem("unknown element " + e)
		}
	}
	return Formula{c, q}, nil
